mapper.select:
select count(*)
  from operation_plan op
  join rollout_instance_execution rie on rie.operation_plan_id = op.id
  join rollback_execution rb on rb.operation_plan_id = op.id
 where op.status = 'UNLOADED'
   and rb.status = 'SUCCEEDED'
   and rie.status = 'UNLOADED'
   and op.resource_id = #{ruleId}
   and op.resource_version = #{ruleVersion}
   and rie.instance_id = #{instanceId}
   and rb.finished_at > #{snapshotReceivedAt}

select count(*)
  from operation_plan op
  join rollout_instance_execution rie on rie.operation_plan_id = op.id
  join rollback_execution rb on rb.operation_plan_id = op.id and rb.status = 'DISPATCHED'
 where op.status = 'UNLOADING'
   and op.resource_id = #{ruleId}
   and op.resource_version = #{ruleVersion}
   and rie.instance_id = #{instanceId}

mapper.update:
update degraded_class
   set reason = #{reason},
       last_seen_at = #{now}
 where agent_id = #{agentId}
   and class_name = #{className}
